CREATE TABLE public.contributions (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    schedule_id uuid NOT NULL,
    member_id uuid NOT NULL,
    position_id uuid NOT NULL,
    ajo_id uuid NOT NULL,
    round_id uuid NOT NULL,
    user_id uuid NOT NULL,
    amount_kobo bigint NOT NULL,
    fee_kobo bigint GENERATED ALWAYS AS ((((amount_kobo * 200) + 5000) / 10000)) STORED,
    total_charge_kobo bigint GENERATED ALWAYS AS ((amount_kobo + (((amount_kobo * 200) + 5000) / 10000))) STORED,
    status public.contribution_status DEFAULT 'pending'::public.contribution_status NOT NULL,
    due_date date NOT NULL,
    paid_at timestamp with time zone,
    overdue_at timestamp with time zone,
    grace_ends_at timestamp with time zone,
    defaulted_at timestamp with time zone,
    recovered_at timestamp with time zone,
    written_off_at timestamp with time zone,
    written_off_reason text,
    superseded_at timestamp with time zone,
    superseded_by_contribution_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT contributions_amount_kobo_check CHECK ((amount_kobo > 0)),
    CONSTRAINT contributions_charge_is_base_plus_fee CHECK ((total_charge_kobo = (amount_kobo + fee_kobo))),
    CONSTRAINT contributions_defaulted_has_timestamp CHECK (((status <> 'defaulted'::public.contribution_status) OR (defaulted_at IS NOT NULL))),
    CONSTRAINT contributions_fee_kobo_check CHECK ((fee_kobo >= 0)),
    CONSTRAINT contributions_paid_has_timestamp CHECK (((status <> 'paid'::public.contribution_status) OR (paid_at IS NOT NULL))),
    CONSTRAINT contributions_superseded_is_complete CHECK (((superseded_at IS NULL) = (superseded_by_contribution_id IS NULL))),
    CONSTRAINT contributions_written_off_has_reason CHECK (((status <> 'written_off'::public.contribution_status) OR ((written_off_at IS NOT NULL) AND (written_off_reason IS NOT NULL))))
);


--

--

COMMENT ON COLUMN public.contributions.amount_kobo IS 'What goes into the round pool. A recipient of a ten-member round receives the sum of these and never the sum of total_charge_kobo. That asymmetry is the entire fee model.';


--

--

COMMENT ON COLUMN public.contributions.total_charge_kobo IS 'NGN 1,020.00 for a member owing NGN 1,000.00. This is the only figure the member is debited, and it is derived, never supplied.';


