    contribution_amount_kobo bigint NOT NULL,
    fee_kobo bigint GENERATED ALWAYS AS ((((contribution_amount_kobo * 200) + 5000) / 10000)) STORED,
    fee_rate_bps smallint DEFAULT 200 NOT NULL,
    status public.fee_status DEFAULT 'accrued'::public.fee_status NOT NULL,
    ledger_transaction_id uuid,
    disclosed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT fees_contribution_amount_kobo_check CHECK ((contribution_amount_kobo > 0)),
    CONSTRAINT fees_fee_kobo_check CHECK ((fee_kobo >= 0)),
    CONSTRAINT fees_fee_rate_bps_check CHECK ((fee_rate_bps = 200))
);


--

--

COMMENT ON TABLE public.fees IS 'AJO.ng''s own record of the 2% charge, separate from the member''s payment so that revenue reporting never depends on joining the payment table.';


